const conferirReserva = async function conferirReserva(reserva, chamar) {
  const base = contextoDoItem(reserva);
  if (!base.reserva_id) return { ...base, vale: false, falha: "sem_reserva" };
  try {
    const vale = await chamar("lili_regua_ainda_vale", { p_id: base.reserva_id });
    if (!vale || vale.status < 200 || vale.status >= 300) return { ...base, vale: false, falha: `ainda_vale_http_${vale?.status}` };
    if (vale.body?.vale !== true) return { ...base, vale: false, motivo: String(vale.body?.motivo || "nao_vale").slice(0, 100) };
    const conversa = await chamar("lili_regua_conversa", { p_id: base.reserva_id });
    if (!conversa || conversa.status < 200 || conversa.status >= 300) {
      return { ...base, vale: false, falha: `conversa_http_${conversa?.status}` };
    }
    const tel = typeof conversa.body === "string" ? conversa.body.trim() : "";
    if (!/^[1-9][0-9]{7,14}$/.test(tel)) return { ...base, vale: false, motivo: "sem_conversa" };
    return { ...base, vale: true, telefone: tel };
  } catch (e) {
    return { ...base, vale: false, falha: String(e?.message ?? e).slice(0, 150) };
  }
};
const hostBloqueado = function hostBloqueado(valor, nome = "N8N_BASE_URL") {
  const texto = String(valor ?? "").trim();
  if (texto === "") {
    throw new Error(`${nome} não definido. O coletor não tem endereço padrão.`);
  }
  if (!/^https?:\/\//.test(texto)) {
    throw new Error(`${nome} não é uma URL`);
  }
  const semBarra = texto.replace(/\/+$/, "");
  const host = semBarra.replace(/^https?:\/\//, "").split("/")[0].split("@").pop().split(":")[0].toLowerCase();
  const bloqueado = "escola_exemplo" + "emilia.com.br";
  if (host === bloqueado || host.endsWith("." + bloqueado)) {
    throw new Error(`${nome} recusado`);
  }
  return semBarra;
};
const erroRedePassageiro = function erroRedePassageiro(erro) {
  const marcas = ["EAI_AGAIN", "ENOTFOUND", "ETIMEDOUT", "ECONNRESET", "socket hang up"];
  const partes = [];
  const visto = new Set();
  let atual = erro;
  for (let i = 0; atual != null && i < 4; i += 1) {
    if (typeof atual === "string") {
      partes.push(atual);
      break;
    }
    if (typeof atual !== "object") {
      partes.push(String(atual));
      break;
    }
    if (visto.has(atual)) break;
    visto.add(atual);
    if (atual.code != null) partes.push(String(atual.code));
    if (atual.message != null) partes.push(String(atual.message));
    atual = atual.cause;
  }
  const texto = partes.join("\n");
  return marcas.some((marca) => texto.includes(marca));
};
const repetirRede = async function repetirRede(fn, rede) {
  const esperas = rede && Array.isArray(rede.esperas) ? rede.esperas : [1000, 3000];
  const dormir = rede && typeof rede.dormir === "function"
    ? rede.dormir
    : (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const total = esperas.length + 1;
  let ultimo;
  for (let i = 0; i < total; i += 1) {
    try {
      return await fn();
    } catch (erro) {
      ultimo = erro;
      if (!erroRedePassageiro(erro) || i === total - 1) throw erro;
      await dormir(esperas[i]);
    }
  }
  throw ultimo;
};
const rpc = async function rpc(nome, corpo, rede) {
  const banco = rede.banco;
  const anon = rede.anon;
  const jwt = rede.jwt;
  const http = rede.http;
  return repetirRede(async () => {
    const res = await http({
      method: "POST",
      url: banco + "/rest/v1/rpc/" + nome,
      headers: {
        "content-type": "application/json",
        apikey: anon,
        authorization: "Bearer " + jwt,
      },
      body: corpo,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (res.statusCode === 401) return { status: 401, body: null };
    const body = res.body == null || res.body === "" ? null : res.body;
    return { status: res.statusCode, body };
  }, rede);
};
const conferir = async () => {
  const reserva = $input.first().json;
  let chamar;
